def tropical_schur(w, x):
    from itertools import permutations
    n = len(w)
    return min(sum(w[p[i]] * x[i] for i in range(n)) for p in permutations(range(n)))

def satake_transform(f, x):
    from itertools import permutations
    n = len(x)
    return min(f([x[p[i]] for i in range(n)]) for p in permutations(range(n)))

def trop_demazure(i, f, x):
    si_x = list(x)
    si_x[i], si_x[i+1] = si_x[i+1], si_x[i]
    return min(f(x), f(si_x) + x[i] - x[i+1])
